document.addEventListener("DOMContentLoaded",()=>{const n=document.querySelectorAll("[data-filter]"),t=document.querySelector("#filterSummary");n.forEach(i=>{i.addEventListener("click",()=>{n.forEach(n=>{n.classList.remove("active","btn-primary"),n.classList.add("btn-outline-secondary"),n.setAttribute("aria-pressed","false")}),i.classList.remove("btn-outline-secondary"),i.classList.add("active","btn-primary"),i.setAttribute("aria-pressed","true"),t&&(t.textContent=`Выбран фильтр: ${i.dataset.filter}`)})})});